import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import test from 'node:test';
import {createBalanceClient} from '../src/client.mjs';
import {singleFlight} from '../src/pending.mjs';
import {resolveBalance} from '../src/resolve.mjs';

function deferred() {
  let resolve;
  let reject;
  const promise = new Promise((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return {promise, resolve, reject};
}

test('only identical ordered pairs share pending requests; original strings reach load', async () => {
  const pairs = [
    ['tenant-a', 'shared'],
    ['tenant-b', 'shared'],
    ['a:b', 'c'],
    ['a', 'b:c'],
    ['left', 'right'],
    ['right', 'left'],
    ['', ':'],
    [':', ''],
    ['租户\u0000"\\', '账户:'],
  ];
  const gates = pairs.map(deferred);
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return gates[pairs.findIndex(pair => pair[0] === args[0] && pair[1] === args[1])].promise;
  });
  const requests = pairs.map(pair => client(...pair));
  requests.forEach((request, index) => {
    assert.ok(request instanceof Promise);
    assert.strictEqual(client(...pairs[index]), request);
  });
  assert.equal(new Set(requests).size, pairs.length);
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  const values = pairs.map((_, index) => ({balanceMinor: index, currency: 'EUR'}));
  gates.forEach((gate, index) => gate.resolve(values[index]));
  const results = await Promise.all(requests);
  results.forEach((value, index) => assert.strictEqual(value, values[index]));
});

test('fulfillment clears only its own entry and never persists values', async () => {
  const gates = [deferred(), deferred(), deferred()];
  let calls = 0;
  const client = createBalanceClient(() => gates[calls++].promise);
  const first = client('t', 'a');
  const other = client('t', 'b');
  gates[0].resolve({balanceMinor: 0, currency: 'JPY'});
  await first;
  assert.strictEqual(client('t', 'b'), other);
  const next = client('t', 'a');
  assert.notStrictEqual(next, first);
  assert.strictEqual(client('t', 'a'), next);
  gates[1].resolve('other');
  gates[2].resolve('fresh');
  assert.deepEqual(await Promise.all([other, next]), ['other', 'fresh']);
  assert.equal(calls, 3);
});

test('plain loader values are Promises, share pending work, and reload after fulfillment', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ++calls);
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  assert.equal(await first, 1);
  const next = client('t', 'a');
  assert.notStrictEqual(next, first);
  assert.equal(await next, 2);
});

test('singleFlight preserves its generic key and loader argument interface', async () => {
  const key = {};
  const args = [{}, 'account', 42];
  let calls = 0;
  const flight = singleFlight((...received) => {
    assert.deepEqual(received, args);
    return ++calls;
  });
  const first = flight(key, ...args);
  assert.strictEqual(flight(key, ...args), first);
  assert.equal(await first, 1);
  assert.equal(await flight(key, ...args), 2);
});

// Strict subprocesses catch ignored cleanup rejections without leaking them into
// the test runner, and cover both loader failure modes through recovery.
for (const failure of ['reject', 'throw']) {
  test(`${failure}: Promise identity, exact error propagation, retry, and no extra unhandled rejection`, () => {
    const clientUrl = new URL('../src/client.mjs', import.meta.url).href;
    const resolveUrl = new URL('../src/resolve.mjs', import.meta.url).href;
    const script = `
      import assert from 'node:assert/strict';
      import {createBalanceClient} from ${JSON.stringify(clientUrl)};
      import {resolveBalance} from ${JSON.stringify(resolveUrl)};
      const error = new Error('lookup failed');
      const value = {balanceMinor: -125, currency: 'GBP'};
      let calls = 0;
      const client = createBalanceClient(() => {
        calls++;
        if (calls <= 2) {
          ${failure === 'throw' ? 'throw error;' : 'return Promise.reject(error);'}
        }
        return value;
      });
      let first;
      assert.doesNotThrow(() => { first = client('tenant', 'account'); });
      assert.ok(first instanceof Promise);
      assert.strictEqual(client('tenant', 'account'), first);
      await assert.rejects(first, actual => actual === error);
      await assert.rejects(resolveBalance(client, 'tenant', 'account'), actual => actual === error);
      assert.equal(calls, 2);
      assert.strictEqual(await client('tenant', 'account'), value);
      assert.equal(calls, 3);
      await new Promise(resolve => setImmediate(resolve));
    `;
    const result = spawnSync(process.execPath, ['--unhandled-rejections=strict', '--input-type=module', '-e', script], {
      encoding: 'utf8',
      timeout: 10_000,
    });
    assert.ifError(result.error);
    assert.equal(result.status, 0, result.stderr || result.stdout);
  });
}

test('resolveBalance preserves minor units, currencies, and request identity', async () => {
  const balances = [0, -0, -125, 125, Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER];
  const currencies = ['JPY', 'EUR', 'GBP', 'KWD', 'CHF', 'USD'];
  for (const [index, balanceMinor] of balances.entries()) {
    const currency = currencies[index];
    const source = Object.freeze({balanceMinor, currency});
    const client = createBalanceClient(() => source);
    const result = await resolveBalance(client, 'tenant:原', 'account:原');
    assert.deepEqual(result, {tenant: 'tenant:原', account: 'account:原', balanceMinor, currency});
    assert.ok(Object.is(result.balanceMinor, balanceMinor));
  }
});

