artifacts.src/pending.mjs:
export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Invoke after registration so even synchronous loaders share pending work.
    // Cleanup belongs to the returned chain, avoiding a detached rejection.
    const promise = Promise.resolve()
      .then(() => load(...args))
      .then(
        value => {
          pending.delete(key);
          return value;
        },
        error => {
          pending.delete(key);
          throw error;
        },
      );
    pending.set(key, promise);
    return promise;
  };
}

