import assert from 'node:assert/strict';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return {promise, resolve, reject};
}

test('same pair shares the identical promise and forwards original strings', async () => {
  const work = deferred();
  const calls = [];
  const client = createBalanceClient((...args) => { calls.push(args); return work.promise; });
  const first = client('tenant:一', 'account:二');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('tenant:一', 'account:二'), first);
  await Promise.resolve();
  assert.deepEqual(calls, [['tenant:一', 'account:二']]);
  const value = {balanceMinor: 0, currency: 'JPY'};
  work.resolve(value);
  assert.strictEqual(await first, value);
});

test('tenant, account, ordering, delimiters and escaped strings identify independent pairs', async () => {
  const pairs = [
    ['tenant-a', 'shared'], ['tenant-b', 'shared'], ['tenant-a', 'other'],
    ['a:b', 'c'], ['a', 'b:c'], ['left', 'right'], ['right', 'left'],
    ['', ':'], [':', ''], ['a"', '\\b'], ['a', '"\\b'],
  ];
  const work = pairs.map(() => deferred());
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return work[pairs.findIndex(pair => pair[0] === args[0] && pair[1] === args[1])].promise;
  });
  const requests = pairs.map(pair => client(...pair));
  assert.equal(new Set(requests).size, pairs.length);
  pairs.forEach((pair, i) => assert.strictEqual(client(...pair), requests[i]));
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  work.forEach((item, i) => item.resolve(i));
  assert.deepEqual(await Promise.all(requests), pairs.map((_, i) => i));
});

test('fulfillment expires the entry and never caches a balance', async () => {
  let calls = 0;
  const client = createBalanceClient(() => ({balanceMinor: ++calls, currency: 'EUR'}));
  const first = client('t', 'a');
  assert.strictEqual(client('t', 'a'), first);
  assert.equal((await first).balanceMinor, 1);
  const next = client('t', 'a');
  assert.notStrictEqual(next, first);
  assert.equal((await next).balanceMinor, 2);
});

test('rejection propagates unchanged, expires the entry, and has no unhandled child rejection', async () => {
  const work = deferred();
  const error = new Error('load failed');
  let calls = 0;
  const client = createBalanceClient(() => ++calls === 1 ? work.promise : 42);
  const first = client('t', 'a');
  assert.strictEqual(client('t', 'a'), first);
  const checked = assert.rejects(first, actual => actual === error);
  work.reject(error);
  await checked;
  const retry = client('t', 'a');
  assert.notStrictEqual(retry, first);
  assert.equal(await retry, 42);
  assert.equal(calls, 2);
  // The test runner reports unhandled rejections during this event-loop turn.
  await new Promise(resolve => setImmediate(resolve));
});

test('synchronous throws become shared rejected promises and allow retry', async () => {
  const error = new Error('sync failure');
  let calls = 0;
  const client = createBalanceClient(() => {
    if (++calls === 1) throw error;
    return 0;
  });
  let first;
  assert.doesNotThrow(() => { first = client('t', 'a'); });
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  await assert.rejects(first, actual => actual === error);
  assert.equal(await client('t', 'a'), 0);
  assert.equal(calls, 2);
  await new Promise(resolve => setImmediate(resolve));
});

test('settling one tenant leaves another tenant request pending', async () => {
  const a = deferred(), b = deferred();
  const client = createBalanceClient(tenant => tenant === 'a' ? a.promise : b.promise);
  const first = client('a', 'shared');
  const other = client('b', 'shared');
  a.resolve(10);
  assert.equal(await first, 10);
  assert.strictEqual(client('b', 'shared'), other);
  b.resolve(20);
  assert.equal(await other, 20);
});

test('singleFlight retains its explicit key and loader argument interface', async () => {
  const key = {};
  const calls = [];
  const get = singleFlight((...args) => { calls.push(args); return 'value'; });
  const first = get(key, 't', 'a');
  assert.strictEqual(get(key, 'ignored'), first);
  assert.equal(await first, 'value');
  assert.deepEqual(calls, [['t', 'a']]);
});

test('resolver preserves monetary values and currencies exactly', async () => {
  for (const [balanceMinor, currency] of [
    [0, 'JPY'], [-125, 'EUR'], [12345, 'KWD'],
    [Number.MAX_SAFE_INTEGER, 'CHF'], [Number.MIN_SAFE_INTEGER, 'GBP'],
