artifacts.src/pending.mjs:
export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);
    // Normalize plain values and synchronous throws into promise outcomes.
    const promise = Promise.resolve().then(() => load(...args));
    pending.set(key, promise);
    const clear = () => { pending.delete(key); };
    // Handle both outcomes without leaving a rejected child promise.
    promise.then(clear, clear);
    return promise;
  };
}

