import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import test from 'node:test';
import {createBalanceClient} from './src/client.mjs';
import {singleFlight} from './src/pending.mjs';
import {resolveBalance} from './src/resolve.mjs';

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return {promise, resolve, reject};
}

test('same pair shares the identical pending promise and original arguments', async () => {
  const work = deferred();
  const calls = [];
  const client = createBalanceClient((...args) => {
    calls.push(args);
    return work.promise;
  });
  const first = client(' tenant:一 ', ' account:二 ');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client(' tenant:一 ', ' account:二 '), first);
  await Promise.resolve();
  assert.deepEqual(calls, [[' tenant:一 ', ' account:二 ']]);
  assert.strictEqual(client(' tenant:一 ', ' account:二 '), first);
  const value = {balanceMinor: 0, currency: 'JPY'};
  work.resolve(value);
  assert.strictEqual(await first, value);
});

test('tenant, account, ordering and delimiter boundaries isolate pending work', async () => {
  const pairs = [
    ['tenant-a', 'shared'], ['tenant-b', 'shared'],
    ['tenant-a', 'other'], ['a:b', 'c'], ['a', 'b:c'],
    ['a', 'b'], ['b', 'a'], ['', ':'], [':', ''],
    ['a",[', '\\b'], ['a', '",[\\b'],
  ];
  const calls = [];
  const work = pairs.map(() => deferred());
  const client = createBalanceClient((...args) => {
    const index = calls.length;
    calls.push(args);
    return work[index].promise;
  });
  const promises = pairs.map(pair => client(...pair));
  assert.equal(new Set(promises).size, pairs.length);
  await Promise.resolve();
  assert.deepEqual(calls, pairs);
  for (let i = 0; i < pairs.length; i++) {
    assert.strictEqual(client(...pairs[i]), promises[i]);
    work[i].resolve(i);
  }
  assert.deepEqual(await Promise.all(promises), pairs.map((_, i) => i));
});

test('fulfillment clears only the settled request and later calls reload', async () => {
  const slow = deferred();
  let loads = 0;
  const client = createBalanceClient((tenant) => {
    loads++;
    return tenant === 'slow' ? slow.promise : {balanceMinor: loads, currency: 'EUR'};
  });
  const pending = client('slow', 'account');
  const first = client('fast', 'account');
  const firstValue = await first;
  const second = client('fast', 'account');
  assert.notStrictEqual(second, first);
  assert.notDeepEqual(await second, firstValue);
  assert.strictEqual(client('slow', 'account'), pending);
  assert.equal(loads, 3);
  slow.resolve('done');
  assert.equal(await pending, 'done');
});

for (const synchronous of [false, true]) {
  test(`${synchronous ? 'synchronous throw' : 'asynchronous rejection'} propagates and permits retry`, async () => {
    const failure = new Error('lookup failed');
    const work = deferred();
    let loads = 0;
    const client = createBalanceClient(() => {
      if (++loads > 1) return {balanceMinor: -42, currency: 'GBP'};
      if (synchronous) throw failure;
      return work.promise;
    });
    let first;
    assert.doesNotThrow(() => { first = client('t', 'a'); });
    assert.ok(first instanceof Promise);
    assert.strictEqual(client('t', 'a'), first);
    const rejected = assert.rejects(first, error => error === failure);
    if (!synchronous) work.reject(failure);
    await rejected;
    const retry = client('t', 'a');
    assert.notStrictEqual(retry, first);
    assert.deepEqual(await retry, {balanceMinor: -42, currency: 'GBP'});
    assert.equal(loads, 2);
  });
}

test('plain loader results are promises and are not persisted', async () => {
  let loads = 0;
  const client = createBalanceClient(() => ++loads);
  const first = client('t', 'a');
  assert.ok(first instanceof Promise);
  assert.strictEqual(client('t', 'a'), first);
  assert.equal(await first, 1);
  assert.equal(await client('t', 'a'), 2);
});

test('singleFlight keeps its exported key-and-arguments interface', async () => {
  const calls = [];
  const key = {};
  const get = singleFlight((...args) => { calls.push(args); return args; });
  const first = get(key, 'tenant', 'account');
  assert.strictEqual(get(key, 'ignored'), first);
  assert.deepEqual(await first, ['tenant', 'account']);
  assert.deepEqual(calls, [['tenant', 'account']]);
  assert.deepEqual(await get(key, 'new'), ['new']);
});

test('resolveBalance preserves monetary values, currency and request identity', async () => {
  for (const balanceMinor of [0, -1, 12345, Number.MAX_SAFE_INTEGER, Number.MIN_SAFE_INTEGER]) {
    for (const currency of ['EUR', 'JPY', 'KWD']) {
      const value = Object.freeze({balanceMinor, currency});
      const result = await resolveBalance(createBalanceClient(() => value), 'tenant', 'account');
      assert.deepEqual(result, {tenant: 'tenant', account: 'account', balanceMinor, currency});
    }
  }
});

test('resolveBalance propagates the original lookup error', async () => {
  const failure = new Error('backend unavailable');
  await assert.rejects(
    resolveBalance(createBalanceClient(() => { throw failure; }), 't', 'a'),
    error => error === failure,
  );
});

test('handled lookup failures produce no extra unhandled rejection', () => {
  const result = spawnSync(process.execPath, ['--unhandled-rejections=strict', '--input-type=module', '-e', `
    import assert from 'node:assert/strict';
    import {createBalanceClient} from './src/client.mjs';
    for (const load of [() => Promise.reject(new Error('async')), () => { throw new Error('sync'); }]) {
      const client = createBalanceClient(load);
      await assert.rejects(client('t', 'a'));
      await assert.rejects(client('t', 'a'));
    }
    await new Promise(resolve => setImmediate(resolve));
  `], {cwd: new URL('.', import.meta.url), encoding: 'utf8'});
  assert.ifError(result.error);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.signal, null);
});

