import {singleFlight} from './pending.mjs';

export function createBalanceClient(load) {
  const get = singleFlight(load);
  // Encoding the tuple preserves tenant boundaries and embedded delimiters.
  return (tenant, account) => get(JSON.stringify([tenant, account]), tenant, account);
}

artifacts.src/pending.mjs:
export function singleFlight(load) {
  const pending = new Map();
  return (key, ...args) => {
    if (pending.has(key)) return pending.get(key);

    // Register before invoking load, and turn synchronous throws into rejections.
    const promise = Promise.resolve().then(() => load(...args));
    pending.set(key, promise);
    const clear = () => { pending.delete(key); };
    // Handle both outcomes so the cleanup branch cannot reject unobserved.
    promise.then(clear, clear);
    return promise;
  };
}

